import { createContext, useState, useEffect } from "react";

export const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
  const [userId, setUserId] = useState(localStorage.getItem("userId") || null);
  const [fullName, setFullName] = useState(
    localStorage.getItem("full_name") || ""
  );

  // Sync state with localStorage on mount only
  useEffect(() => {
    console.log("AuthContext useEffect: Syncing with localStorage", {
      userId: localStorage.getItem("userId"),
      full_name: localStorage.getItem("full_name"),
    });
  }, []);

  const login = (id, full_name) => {
    console.log("AuthContext login:", { id, full_name });
    localStorage.setItem("userId", id);
    localStorage.setItem("full_name", full_name);
    setUserId(id);
    setFullName(full_name);
  };

  const logout = () => {
    console.log("AuthContext logout");
    localStorage.removeItem("userId");
    localStorage.removeItem("full_name");
    setUserId(null);
    setFullName("");
  };

  return (
    <AuthContext.Provider value={{ userId, fullName, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
};
